package me.rakkoon69.rakunloots.config;
import me.rakkoon69.rakunloots.items.ItemReference;
import me.rakkoon69.rakunloots.roll.LootChance;
import java.util.*;
public class ProbeLargeFirstDraw {
    public static void main(String[] args) {
        int n=10000, first=9900;
        List<ContentEntry> entries=new ArrayList<>();
        for(int i=0;i<n;i++) entries.add(new ContentEntry("e"+i,ItemReference.of("","diamond"),1,
                i<first?1:2,OptionalInt.empty()));
        long start=System.nanoTime();
        var chances=LootChance.calculate(new Roll(1,1,entries));
        double totalWeight=first+2.0*(n-first), error=0;
        for(int i=0;i<n;i++) error=Math.max(error,Math.abs(chances.get("e"+i).probability()
                -(i<first?1.0:2.0)/totalWeight));
        System.out.printf(Locale.ROOT,"n=%d light=%.17g expectedLight=%.17g heavy=%.17g expectedHeavy=%.17g maxError=%.12g ms=%.1f%n",
                n,chances.get("e0").probability(),1/totalWeight,chances.get("e9900").probability(),2/totalWeight,
                error,(System.nanoTime()-start)/1e6);
        if(!Double.isFinite(error)||error>1e-9) throw new AssertionError("first-draw exact weight share exceeds1e-9");
    }
}
